import {createFireVolume} from './fire-volume.js';
import {spreadSources,rearSources} from './fire-spread.js';
import * as T from 'three';

export function createFireEffects(scene){
const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ctx=canvas.getContext('2d');const g=ctx.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,255,255,0.95)');g.addColorStop(.38,'rgba(255,255,255,0.75)');g.addColorStop(.72,'rgba(255,255,255,0.25)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);const texture=new T.CanvasTexture(canvas);
function puff(){const o=new T.Sprite(new T.SpriteMaterial({map:texture,color:'#42464a',transparent:true,opacity:0,depthWrite:false}));scene.add(o);return o}
const exterior=Array.from({length:90},puff),layers=Array.from({length:5},()=>Array.from({length:28},puff));
const uniform={time:{value:0},power:{value:.2},airflow:{value:0}};
const material=new T.ShaderMaterial({uniforms:uniform,transparent:true,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending,vertexShader:'varying vec2 uvv;uniform float time;uniform float airflow; void main(){uvv=uv;vec3 bent=position;float tip=uv.y*uv.y;float gust=.65+.35*sin(time*1.7);bent.x+=tip*(sin(time*3.1+uv.y*8.)*(.055+airflow*.2)+airflow*.2*gust);bent.z+=tip*sin(time*2.4+uv.y*6.)*(.035+airflow*.15);bent.y+=uv.y*(.5+.5*sin(time*2.8))*.12*airflow;gl_Position=projectionMatrix*modelViewMatrix*vec4(bent,1.);}',fragmentShader:`varying vec2 uvv;uniform float time;uniform float power;uniform float airflow;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}
void main(){vec2 p=uvv;p.x+=sin(p.y*12.-time*(3.+airflow*3.))*.06*airflow*p.y;float n=noise(vec2(p.x*8.,p.y*7.-time*(3.+airflow*2.)));float n2=noise(vec2(p.x*17.+time*.7,p.y*13.-time*5.));float sway=sin(p.y*7.-time*(3.+airflow*2.))*.075*p.y;float width=(1.-p.y)*(.34+.13*n)*(1.-airflow*.18);float shape=1.-smoothstep(width*.3,width,abs(p.x-.5+sway));float top=1.-smoothstep(.52+n*.4,1.,p.y);float a=shape*top*(.55+.45*n2);vec3 color=mix(vec3(1.,.12,.015),vec3(1.,.72,.12),shape*(1.-p.y));color=mix(color,vec3(1.,.95,.62),pow(shape,4.)*pow(1.-p.y,3.));gl_FragColor=vec4(color*(1.+power*.6),a*.86);}`});
const volume=createFireVolume(scene,material);
const flames=Array.from({length:9},(_,i)=>{const o=new T.Mesh(new T.PlaneGeometry(1,1,6,12),material);o.position.set(.15+(i%3)*.95,8.2,4.35+Math.floor(i/3)*.18);o.rotation.y=(i%3-1)*.45;scene.add(o);return o});
const spreadFlames=Array.from({length:21},()=>Array.from({length:3},(_,i)=>{const o=new T.Mesh(new T.PlaneGeometry(1,1,6,12),material);o.rotation.y=(i-1)*.6;o.visible=false;scene.add(o);return o}));const spreadSmoke=Array.from({length:21},()=>Array.from({length:10},puff));
const glow=new T.PointLight('#ff7526',20,14);glow.position.set(1.4,8.4,4.8);scene.add(glow);
const panel=document.createElement('div');panel.className='firestatus';panel.innerHTML='<strong id="firephase">初期冒煙</strong><span>射水／通風連動 · 示意</span><div class="densityrows"></div>';document.querySelector('.command').prepend(panel);const rows=panel.querySelector('.densityrows');let uiElapsed=1,shownHeight=0,shownVent=0;const shownDensity=[0,0,0,0,0],shownDepth=[0,0,0,0,0];
return {update(t,seconds,section,state,dt=.016){const ease=1-Math.exp(-dt*4);shownHeight+=(state.flameHeight-shownHeight)*ease;state.floors.forEach((d,f)=>{shownDensity[f]+=(d-shownDensity[f])*ease;shownDepth[f]+=(state.depths[f]-shownDepth[f])*ease});shownVent+=(state.vent-shownVent)*(1-Math.exp(-dt*2));const gust=.7+.3*Math.sin(t*1.7);uniform.airflow.value=shownVent;const p=state.growth;volume.update(t,{...state,vent:shownVent});uniform.time.value=t;uniform.power.value=p;glow.intensity=(83*p)*(1+Math.sin(t*15)*.09);flames.forEach((o,i)=>{const h=shownHeight*(1+Math.sin(i*2+t*5)*.13);o.scale.set(state.diameter*.8,h,1);o.position.x=1.3+(i%3-1)*state.diameter*.3;o.position.y=7.05+h/2;o.visible=h>.01&&i<3+Math.floor(p*6)});
[...spreadSources(state),...rearSources(state)].forEach((src,k)=>{const power=k===2?0:src.strength;spreadFlames[k].forEach((o,i)=>{const h=Math.min(k>=12&&k%3!==2?2.6:20,shownHeight*power)*(.85+.1*Math.sin(t*4+i));o.visible=power>.01&&h>.01;o.scale.set(state.diameter*.65,h,1);o.position.set(src.x+(i-1)*.2,src.base+h/2,(src.z??4.4)+i*.1)});spreadSmoke[k].forEach((o,i)=>{const q=(t*.13+i/10)%1;o.visible=power>.01;o.position.set(src.x+Math.sin(i*3+q)*q,src.base+1.6+q*4,(src.z??4.8)+(src.z<0?-1:1)*q*(1.3+shownVent*2*gust));o.scale.setScalar(1+q*2);o.material.opacity=power*shownDensity[src.floor]*.35*Math.sin(q*Math.PI)});});
exterior.forEach((o,i)=>{const q=(t*(.075+p*.035)+i/90)%1;const spread=.5+q*(2.5+p*2.4);o.position.set(1.3+q*(2+p*2+shownVent*2*gust)+Math.sin(i*2.4+q*4)*spread*.6,8.7+q*(9+p*5),4.8+q*(3+shownVent*4*gust)+Math.cos(i*1.7)*spread*.5);o.scale.setScalar(1.6+q*(4+p*3));o.material.rotation=Math.sin(i)*.5+q*.5;o.material.color.setRGB(.24-q*.08,.25-q*.07,.26-q*.06);o.material.opacity=(shownDensity[2]*.5)*(1+state.vent*.3)*Math.sin(Math.PI*q)*(.7+(i%3)*.15);});
layers.forEach((floor,f)=>{const d=shownDensity[f],base=f*3.2+.31,top=base+2.82,thickness=shownDepth[f];floor.forEach((o,i)=>{const x=-4.5+(i%7)*1.5,z=-2.8+Math.floor(i/7)*1.75;o.visible=section&&d>.005&&thickness>.01;o.position.set(x+Math.sin(t*.25+i)*.12,top-thickness*(.12+(i%4)*.21),z);o.scale.set(2.6,thickness*1.65,1);o.material.opacity=d*.36;o.material.color.setRGB(.46-d*.3,.47-d*.3,.48-d*.3);});});
uiElapsed+=dt;if(uiElapsed>.2){uiElapsed=0;panel.querySelector('strong').textContent=state.stage;panel.querySelector(':scope > span').textContent='有效射水 '+state.water+' 組 · t²／介入示意';rows.innerHTML=[4,3,2].map(f=>{const d=state.floors[f],name=d<.15?'薄煙':d<.45?'中等':d<.75?'濃煙':'高濃煙';return '<div><b>'+(f+1)+'F</b><i><em style="width:'+Math.round(d*100)+'%"></em></i><span>'+name+'</span></div>'}).join('')}panel.classList.toggle('sectionmode',section);
}};
}
